//@@ ch01-why-event-driven
CH({slug:'ch01-why-event-driven',n:'1',part:'Part I · Foundations',sub:'Small services driven by a loop of consuming and producing events.',end:'Events stay in the stream for whoever needs them next.',scenes:[
{type:'flow',title:'An event-driven microservice, <b>in one picture</b>',cols:3,rows:2,nodes:[{id:'a',t:'Input stream A',c:'blue',col:0,row:0},{id:'b',t:'Input stream B',c:'blue',col:0,row:1},{id:'s',t:'Microservice<br>one business job',c:'green',col:1,row:0,big:1},{id:'st',t:'Private state',c:'violet',col:1,row:1},{id:'o',t:'Output stream',c:'amber',col:2,row:0}],edges:[['a','s'],['b','s'],['s','st'],['s','o']],
 cap:['Small enough to fit in one person’s head, owned by a small team.','Its work is driven by a loop of <b>consuming and producing events</b>.']},
VS('Not the old message passing','Message queue',['A message is read once','Then it is gone','A late consumer misses it'],'Event stream',['Events are not destroyed when read','They stay for any later consumer','Each consumer reads at its own pace'],['The key difference from older message-passing systems.'],'≠'),
PT('Domains and bounded contexts',[['Domain','The whole problem space a business works in.'],['Subdomain','One part of it, often mirroring the org chart.'],['Domain model','The business’s own representation, in its own terms.'],['Bounded context','The boundary around one subdomain’s inputs, outputs, rules and data.']],['Domain-driven design gives the vocabulary for drawing service boundaries.','A bounded context may need one microservice, or several.']),
VS('Align on business needs, not technical layers','Teams by technical layer',['One team owns the app, another the database','Explicit dependencies between teams','A small change ripples across both'],'Teams by business capability',['Code and data owned together','Change it without asking anyone','Some repeated code is the price'],['Repetition is usually far cheaper than tight coupling.']),
PT('Three communication structures',[['Business','How teams and people talk to get work done.','blue'],['Implementation','The code and data models inside one service.','amber'],['Data','How data moves between them: <b>event streams</b>.','green']],['The web of dependencies that results is a communication structure.']),
QT('Conway’s law','Organizations produce designs that *copy their communication structures.*','Melvin Conway’s 1968 observation, paraphrased.'),
RC('1',[['Event-driven','A loop of consume and produce.'],['Durable events','Reading does not destroy them.'],['Bounded contexts','Draw services around business capability.'],['Business alignment','Own code and data together.'],['Data structure','Event streams carry data between teams.']])
]});
//@@ ch02-events-and-streams
CH({slug:'ch02-events-and-streams',n:'2',part:'Part I · Foundations',sub:'What an event is, what a stream is, and why keys matter.',end:'Same key, same partition.',scenes:[
PT('An event is a recorded business fact',[['Single source of truth','It holds everything needed to describe what happened.','blue'],['Immutable','Once published, you can’t edit it.','amber'],['Corrected by a new event','If something was wrong, publish the correction.','green']],['An invoice received, a meeting room booked, a coffee ordered.']),
PT('A stream is a durable, append-only log',[['Immutable'],['Partitioned'],['Indexed by offset'],['Ordered within a partition'],['Durable and replayable'],['Storable indefinitely']],['Producers append at the tail. Consumers start wherever they like.','It lives on an event broker, such as Apache Kafka.']),
PT('Ephemeral messaging, queues and streams',[['Ephemeral messaging','Consumer B subscribes after event 3, and only ever sees 4, 5 and 6.','red'],['Queue','Each event is handed to one consumer, then removed.','amber'],['Event stream','B can start from event 1 and read all six.','green']],['A producer sends events 1 to 6. Consumer B subscribes late.']),
PT('Key, value and header',[['Key','Identifies what the event is about, and picks the partition.','blue'],['Value','The details of what happened.','green'],['Header','Metadata about the record.','amber']],['Events come in three classes: unkeyed, entity and keyed.']),
PL('Keys give data locality',[['Licence plate','The key.'],['Hash the key','The producer picks a partition.'],['Same partition','Every event for that plate lands here.'],['One instance','Per-key work reads only one partition.','green']],['Anything you compute per key needs only one partition.'],{tc:'amber'}),
VS('Repartitioning and copartitioning','Repartitioning',['Rewrite a stream with a new key or partition count','Makes joins and grouping possible','Can introduce out-of-order data'],'Copartitioning',['Two streams share key, partitioner and count','Partition n of each holds the same keys','One instance can join them locally'],[],'+','amber','green'),
RC('2',[['Event','An immutable business fact.'],['Stream','A partitioned, replayable log.'],['Not a queue','Reading does not remove events.'],['Key, value, header','Three parts of a record.'],['Data locality','Same key, same partition.']])
]});
