//@@ ch04-schemas-contracts
CH({slug:'ch04-schemas-contracts',n:'4',part:'Part II · Events and data',sub:'Explicit schemas, safe evolution, and the promise a producer makes about a stream.',end:'Start strict. Loosening is easy; tightening is not.',scenes:[
PL('Serialize, send, deserialize',[['In-memory object','A Person in the producer.'],['Serialize','Checked against the schema. A bad value fails here.'],['Bytes on the stream','Compact and typed.'],['Deserialize','The consumer rebuilds its own object.','green']],['A schema declares names, types, defaults and limits.','If a value doesn’t fit, serialization fails, which is <b>exactly what you want</b>.']),
BR('Without a schema, every consumer guesses',[['Interpretations without schemas',10,null,'red'],['Shared definitions with schemas',2,null,'green']],['Two streams, five consumers each.','Leave out the schema and misreadings multiply.'],{max:10,lw:620}),
PT('Choosing a schema technology',[['Avro','One of the top two for years.','blue'],['Protobuf','The other. Version 3 dropped custom defaults.','green'],['JSON Schema','A reasonable third.','amber'],['Schemaless JSON','Not an option: fields and types are left to guesswork.','red']]),
PT('Evolving without breaking anyone',[['Backward','Readers on the new schema can read old data.','blue'],['Forward','Readers on the old schema can read new data.','amber'],['Full','Both directions.','green'],['Transitive','The guarantee holds across every version, not just the last.','violet']],['A reader can fill a missing field only if its schema gives a default.','Start at <b>full-transitive</b>, the strongest guarantee.']),
VS('A data contract','Service contract',['Describes a service','Its API and behaviour'],'Data contract',['Describes the data in a stream','A promise from the producer to every consumer','Past, present and future'],['Not every stream needs one. A private, single-team stream can skip it.'],'→','blue','green'),
PL('Negotiating a breaking change',[['Tell consumers','Before anything is deployed.'],['Agree a plan','Who migrates, and by when.'],['Publish the new format','Alongside the old.'],['Retire the old','Once the last consumer has moved.','green']],['Breaking changes usually come from shifts in the business itself.']),
RC('4',[['Schemas','Explicit names, types and defaults.'],['Fail fast','Bad data stops at serialization.'],['Formats','Avro, Protobuf or JSON Schema.'],['Compatibility','Start at full-transitive.'],['Data contracts','The promise about a stream.']])
]});
//@@ ch05-designing-events
CH({slug:'ch05-designing-events',n:'5',part:'Part II · Events and data',sub:'State or delta: the choice that decides how coupled your consumers become.',end:'Deltas inside. State across boundaries.',scenes:[
VS('Two basic kinds: state and delta','State event',['The level: what the entity is now','Key identifies the entity','Value carries its whole public state','Like a database row'],'Delta event',['The edge: what changed','Named as a past-tense verb','itemAddedToCart, orderShipped','Consumers must apply them in order'],['Every change has an initial state, a delta, and a final state.'],'or','green','amber'),
PT('Event-carried state transfer',[['State goes to every consumer','No call back to the producer.','blue'],['Easy materialization','Upsert by key and you have a table.','green'],['Strong decoupling','Nobody depends on the producer’s internal logic.','amber']],['Consumers can still see what changed: compare with the previous event for the key.']),
VS('Current state, or before and after?','Before/after events',['Common from change-data capture','Show a transition in one event','Heavier, and can’t be compacted as cleanly','Expose the producer’s transitions'],'Current-state events',['Lean and simple','Compactable: about one event per key','Hide why things changed','Consumers keep the slice they care about'],['The verdict: current-state events win for streams.']),
VS('Deltas inside a domain: event sourcing','CRUD',['Overwrites state in place','Read-after-write consistency','Familiar','Concurrent writes to one entity conflict'],'Event sourcing',['Appends every delta to a log','Rebuilds state by replaying them','Writing and aggregating scale separately','Eventually consistent'],[],'or','blue','violet'),
{type:'flow',title:'Why deltas make poor public contracts',cols:3,rows:3,nodes:[{id:'p',t:'Cart service<br>adds a new delta',c:'red',col:0,row:1,big:1},{id:'a',t:'Consumer 1<br>copied the cart logic',c:'amber',col:1,row:0},{id:'b',t:'Consumer 2<br>copied the cart logic',c:'amber',col:1,row:1},{id:'c',t:'Consumer 3<br>copied the cart logic',c:'amber',col:1,row:2},{id:'x',t:'All three<br>now compute it wrong',c:'red',col:2,row:1}],edges:[['p','a'],['p','b'],['p','c'],['a','x'],['b','x'],['c','x']],
 cap:['Each consumer rebuilt the producer’s logic to turn deltas into state.','Then the producer ships a feature. Any exposed event is <b>a public contract</b>.']},
QT('The rule of thumb','*Deltas inside* a bounded context. *State across* boundaries.','Use deltas for event sourcing within a context. Publish state to everyone else.'),
RC('5',[['State events','The whole entity, keyed.'],['Delta events','What changed.'],['ECST','State carried to every consumer.'],['Current state wins','Lean and compactable.'],['Event sourcing','Fine inside one context.'],['Public deltas','Couple consumers to your logic.']])
]});
//@@ ch06-integrating-existing
CH({slug:'ch06-integrating-existing',n:'6',part:'Part II · Events and data',sub:'Liberating data from existing databases without the dual-write trap.',end:'Liberate the most-used data first.',scenes:[
{type:'flow',title:'What is data liberation?',cols:3,rows:3,nodes:[{id:'m',t:'Monolith<br>database',c:'amber',col:0,row:1,big:1},{id:'s',t:'Event streams<br>new source of truth',c:'green',col:1,row:1,big:1},{id:'a',t:'Service A',c:'blue',col:2,row:0},{id:'b',t:'Service B',c:'blue',col:2,row:1},{id:'c',t:'Analytics',c:'blue',col:2,row:2}],edges:[['m','s'],['s','a'],['s','b'],['s','c']],
 cap:['Existing systems hold data many other domains need: products, prices, stock, payments.','Publish those data sets to streams. Point-to-point dependencies show what to free first.']},
PL('The dual-write antipattern',[['Write to the database','Succeeds.'],['Write to the stream','A second, independent write. No shared transaction.'],['It fails for good','An invalid schema, or a long outage.'],['Diverged','The two copies never agree again.']],['The tempting shortcut: write to your database, then write to the stream.','Retries help with blips, not with everything.'],{acc:'red',stop:2,stopLabel:'diverged'}),
PT('Three ways to liberate data',[['Change-data capture','Tail the database log. Sees every change and hard deletes. Exposes the internal model.','green'],['Query-based polling','Query on a schedule. Simple. Misses intermediate changes and hard deletes.','amber'],['Outbox table','The app writes events in the same transaction. Hides internals. Needs app changes.','blue']],['All three must capture the whole data set, then keep up with every change.']),
PL('Change-data capture and the snapshot',[['Snapshot in chunks','Select the table piece by piece. No locks.'],['Watermarks','Mark where each chunk sits in the log.'],['Interleave','Merge chunk rows with live log events.'],['Caught up','From here, just tail the log.','green']],['The log only holds a short window, so you first need everything that exists.','A classic snapshot locks the table for hours. This approach does not.'],{tc:'teal'}),
PT('Good habits',[['Timestamp order','Use the source record’s last-updated time, not publish time.'],['Ready-made connectors','Kafka Connect, Debezium, Apache NiFi.'],['At-least-once is fine','Upserts of entity data are idempotent.']]),
RC('6',[['Data liberation','Publish cross-domain data to streams.'],['No dual writes','Two writes, no transaction.'],['CDC','Tail the log.'],['Polling','Simple, but lossy.'],['Outbox','Transactional, hides internals.']])
]});
//@@ ch07-denormalization
CH({slug:'ch07-denormalization',n:'7',part:'Part II · Events and data',sub:'Join once at the source, so every consumer doesn’t have to.',end:'Join once. Publish what consumers need.',scenes:[
VS('Relational streams make every consumer join','Normalized streams',['Items in one stream, merchants in another','Ads, search, item pages and deals all need both','Each does the same streaming join','Harder, slower and pricier than a table join'],'Denormalized once',['The merchant’s fields ride inside the item event','Everything a consumer needs is in the event','Simpler consumers, simpler frameworks'],['Databases resolve relationships at query time. Streams work best when they don’t have to.']),
VS('Where to eventify','Inside the database: outbox',['Join when writing the outbox row','Transactional with the source','Adds load to the source database'],'A dedicated service',['Consumes the raw streams','Joins and standardizes them','Publishes the enriched stream'],['Joins only, no business logic. Filters belong downstream.'],'or','blue','green'),
{type:'stats',title:'Denormalize, and every change must flow through',items:[{v:1,l:'merchant buys premium status',c:'amber'},{v:2000,l:'item events must be re-emitted',c:'red'}],
 cap:['Copy merchant data into each item, and a merchant change touches every one of its items.','Otherwise the stream stops reflecting reality, <b>permanently</b>.']},
PT('What goes in the event?',[['Merchant fields: in','Small, and they rarely change.','green'],['Inventory: out','It can change constantly. Picture a Black Friday sale.','red'],['Top reviews: out','Large. Every change would re-send them all.','red']],['Two factors dominate: how <b>often</b> it changes, and how <b>big</b> it is.','Join both in and frequency multiplies size.']),
VS('Slowly changing dimensions','Type 1',['Overwrite with the latest value','Consumers see only what is true now'],'Type 2',['Keep each version with its validity period','Consumers can ask what was true then'],['A merchant’s name rarely changes. But it can, at any moment.'],'or','blue','violet'),
RC('7',[['Stream joins are costly','Avoid making everyone repeat them.'],['Eventify once','At the outbox, or in a service.'],['Fan-out','A dimension change re-emits its facts.'],['Frequency and size','Decide what to include.'],['SCD','Overwrite, or keep history.']])
]});
